package com.smartdoc.ai.provider;
import com.fasterxml.jackson.databind.*; import org.springframework.http.*; import org.springframework.web.client.*; import java.net.URI; import java.util.*;
public class OpenAiChatCompletionsAdapter implements ProviderAdapter { private final RestTemplate http; private final ObjectMapper json; private final int cap;
 public OpenAiChatCompletionsAdapter(RestTemplate h,ObjectMapper j,int c){http=h;json=j;cap=c;}
 public AiProviderProtocol protocol(){return AiProviderProtocol.OPENAI_CHAT_COMPLETIONS;}
 public ProviderResponse complete(AiProviderConfig config,String key,TextCompletionRequest request){try{URI endpoint=URI.create(config.getBaseUrl().replaceAll("/+$","")+"/").resolve("chat/completions");HttpHeaders headers=new HttpHeaders();headers.setContentType(MediaType.APPLICATION_JSON);headers.setBearerAuth(key);Map<String,Object> body=new LinkedHashMap<>();body.put("model",config.getModel());body.put("temperature",0.2);body.put("max_tokens",request.getMaxOutputTokens());List<Map<String,String>> messages=new ArrayList<>();if(!request.getSystem().isBlank())messages.add(Map.of("role","system","content",request.getSystem()));messages.add(Map.of("role","user","content",request.getPrompt()));body.put("messages",messages);ResponseEntity<byte[]> response=http.exchange(endpoint,HttpMethod.POST,new HttpEntity<>(body,headers),byte[].class);long declared=response.getHeaders().getContentLength();byte[] bytes=response.getBody()==null?new byte[0]:response.getBody();if(declared>cap||bytes.length>cap)throw new ProviderHttpException("RESPONSE_TOO_LARGE",502);JsonNode root=json.readTree(bytes);String answer=root.path("choices").path(0).path("message").path("content").asText();if(answer==null||answer.trim().isEmpty())throw new ProviderHttpException("INVALID_PROVIDER_RESPONSE",502);return new ProviderResponse(answer);}catch(ProviderHttpException e){throw e;}catch(HttpClientErrorException e){throw new ProviderHttpException(e.getStatusCode().value()==401||e.getStatusCode().value()==403?"PROVIDER_AUTH_FAILED":"PROVIDER_REQUEST_FAILED",502);}catch(HttpServerErrorException e){throw new ProviderHttpException("PROVIDER_UNAVAILABLE",502);}catch(ResourceAccessException e){throw new ProviderHttpException("PROVIDER_TIMEOUT",504);}catch(Exception e){throw new ProviderHttpException("INVALID_PROVIDER_RESPONSE",502);}}
 public ProviderResponse probe(AiProviderConfig c,String k){return complete(c,k,new TextCompletionRequest("","Reply with OK only.",1));} public ProviderResponse vision(AiProviderConfig c,String k,VisionCompletionRequest r){throw new ProviderHttpException("UNSUPPORTED_CAPABILITY",400);}
}
